// Harness ICollection<T>::ForeachItem by creating a minimal concrete ICollection<int>
// and verifying that the functor sees each element exactly once and in the same order.
class IntCollection final : public opendnp3::ICollection<int> {
public:
    explicit IntCollection(const std::vector<int>& v) : data(v) {}
    std::size_t Count() const override { return data.size(); }
    void Foreach(opendnp3::IVisitor<int>& visitor) const override {
        for (const auto& val : data) visitor.OnValue(val);
    }
private:
    std::vector<int> data;
};

